  /**
   * @method
   * @name bitmex#fetchOrderBook
   * @description fetches information on open orders with bid (buy) and ask
   * (sell) prices, volumes and other data
   * @see https://www.bitmex.com/api/explorer/#!/OrderBook/OrderBook_getL2
   * @param {string} symbol unified symbol of the market to fetch the order book
   * for
   * @param {int} [limit] the maximum amount of order book entries to return
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} an [order book structure]{@link
   * https://docs.ccxt.com/?id=order-book-structure}
   */
  std::shared_future<ccxt::any>
  fetchOrderBook(ccxt::any symbol, ccxt::any limit = ccxt::any{},
                 ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 ccxt::any market = this->market(symbol);
                 ccxt::any request = ccxt::dict{
                     {std::string("symbol"),
                      ::getValue(market, std::string("id"))},
                 };
                 if (isTrue(!isEqual(limit, ccxt::any{}))) {
                   ::setValue(request, std::string("depth"), limit);
                 }
                 ccxt::any response = awaitValue(
                     this->publicGetOrderBookL2(this->extend(request, params)));
                 ccxt::any result = ccxt::dict{
                     {std::string("symbol"), symbol},
                     {std::string("bids"), ccxt::list{}},
                     {std::string("asks"), ccxt::list{}},
                     {std::string("timestamp"), ccxt::any{}},
                     {std::string("datetime"), ccxt::any{}},
                     {std::string("nonce"), ccxt::any{}},
                 };
                 ccxt::any orders = this->toArray(response);
                 for (ccxt::any i = 0; isLessThan(i, getArrayLength(orders));
                      postFixIncrement(i)) {
                   ccxt::any order = ::getValue(orders, i);
                   ccxt::any side =
                       (isTrue((isEqual(::getValue(order, std::string("side")),
                                        std::string("Sell"))))
                            ? ccxt::any(std::string("asks"))
                            : ccxt::any(std::string("bids")));
                   ccxt::any amount = this->convertFromRawQuantity(
                       symbol, this->safeString(order, std::string("size")));
                   ccxt::any price =
                       this->safeNumber(order, std::string("price"));
                   // https://github.com/ccxt/ccxt/issues/4926
                   // https://github.com/ccxt/ccxt/issues/4927
                   // the exchange sometimes returns null price in the orderbook
                   if (isTrue(!isEqual(price, ccxt::any{}))) {
                     arrayPush(::getValue(result, side),
                               ccxt::list{price, amount});
                   }
                 }
                 ::setValue(
                     result, std::string("bids"),
                     this->sortBy(::getValue(result, std::string("bids")), 0,
                                  true));
                 ::setValue(
                     result, std::string("asks"),
                     this->sortBy(::getValue(result, std::string("asks")), 0));
                 return result;
               })
        .share();
  }

  /**
   * @method
   * @name bitmex#fetchOrder
   * @description fetches information on an order made by the user
   * @see https://www.bitmex.com/api/explorer/#!/Order/Order_getOrders
   * @param {string} id the order id
   * @param {string} symbol unified symbol of the market the order was made in
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} An [order structure]{@link
   * https://docs.ccxt.com/?id=order-structure}
   */
  std::shared_future<ccxt::any>
  fetchOrder(ccxt::any id, ccxt::any symbol = ccxt::any{},
             ccxt::any params = ccxt::dict{}) override {
    return std::async(std::launch::deferred,
                      [=]() mutable -> ccxt::any {
                        ccxt::any filter = ccxt::dict{
                            {std::string("filter"),
                             ccxt::dict{
                                 {std::string("orderID"), id},
                             }},
                        };
                        ccxt::any response = awaitValue(this->fetchOrders(
                            symbol, ccxt::any{}, ccxt::any{},
                            this->deepExtend(filter, params)));
                        ccxt::any numResults = getArrayLength(response);
                        if (isTrue(isEqual(numResults, 1))) {
                          return ::getValue(response, 0);
                        }
                        throw OrderNotFound(toString(add(
                            add(add(this->id, std::string(": The order ")), id),
                            std::string(" not found."))));
                        return ccxt::any{};
                      })
        .share();
  }

  /**
   * @method
   * @name bitmex#fetchOrders
   * @see https://www.bitmex.com/api/explorer/#!/Order/Order_getOrders
   * @description fetches information on multiple orders made by the user
   * @param {string} symbol unified market symbol of the market orders were made
   * in
   * @param {int} [since] the earliest time in ms to fetch orders for
   * @param {int} [limit] the maximum number of order structures to retrieve
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {int} [params.until] the earliest time in ms to fetch orders for
   * @param {boolean} [params.paginate] default false, when true will
   * automatically paginate by calling this endpoint multiple times. See in the
   * docs all the [availble
   * parameters](https://github.com/ccxt/ccxt/wiki/Manual#pagination-params)
   * @returns {Order[]} a list of [order structures]{@link
   * https://docs.ccxt.com/?id=order-structure}
   */
  std::shared_future<ccxt::any>
  fetchOrders(ccxt::any symbol = ccxt::any{}, ccxt::any since = ccxt::any{},
              ccxt::any limit = ccxt::any{},
              ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 ccxt::any paginate = false;
                 ccxt::any paginateparamsVariable = this->handleOptionAndParams(
                     params, std::string("fetchOrders"),
                     std::string("paginate"));
                 paginate = ::getValue(paginateparamsVariable, 0);
                 params = ::getValue(paginateparamsVariable, 1);
                 if (isTrue(paginate)) {
                   return awaitValue(this->fetchPaginatedCallDynamic(
                       std::string("fetchOrders"), symbol, since, limit, params,
                       100));
                 }
                 ccxt::any market = ccxt::any{};
                 ccxt::any request = ccxt::dict{};
                 if (isTrue(!isEqual(symbol, ccxt::any{}))) {
                   market = this->market(symbol);
                   ::setValue(request, std::string("symbol"),
                              ::getValue(market, std::string("id")));
                 }
                 if (isTrue(!isEqual(since, ccxt::any{}))) {
                   ::setValue(request, std::string("startTime"),
                              this->iso8601(since));
                 }
                 if (isTrue(!isEqual(limit, ccxt::any{}))) {
                   ::setValue(request, std::string("count"), limit);
                 }
                 ccxt::any until = this->safeInteger2(
                     params, std::string("until"), std::string("endTime"));
                 if (isTrue(!isEqual(until, ccxt::any{}))) {
                   params =
                       this->omit(params, ccxt::list{std::string("until")});
                   ::setValue(request, std::string("endTime"),
                              this->iso8601(until));
                 }
                 request = this->deepExtend(request, params);
                 // why the hassle? urlencode in python is kinda broken for
                 // nested dicts. E.g. self.urlencode({"filter": {"open":
                 // True}}) will return "filter={'open':+True}" Bitmex doesn't
                 // like that. Hence resorting to this hack.
                 if (isTrue(inOp(request, std::string("filter")))) {
                   ::setValue(
                       request, std::string("filter"),
                       this->json(::getValue(request, std::string("filter"))));
                 }
                 ccxt::any response =
                     awaitValue(this->privateGetOrder(request));
                 return this->parseOrders(response, market, since, limit);
               })
        .share();
  }

  /**
   * @method
   * @name bitmex#fetchOpenOrders
   * @description fetch all unfilled currently open orders
   * @see https://www.bitmex.com/api/explorer/#!/Order/Order_getOrders
   * @param {string} symbol unified market symbol
   * @param {int} [since] the earliest time in ms to fetch open orders for
   * @param {int} [limit] the maximum number of  open orders structures to
   * retrieve
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {Order[]} a list of [order structures]{@link
   * https://docs.ccxt.com/?id=order-structure}
   */
  std::shared_future<ccxt::any>
  fetchOpenOrders(ccxt::any symbol = ccxt::any{}, ccxt::any since = ccxt::any{},
                  ccxt::any limit = ccxt::any{},
                  ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 ccxt::any request = ccxt::dict{
                     {std::string("filter"),
                      ccxt::dict{
                          {std::string("open"), true},
                      }},
                 };
                 return awaitValue(this->fetchOrders(
                     symbol, since, limit, this->deepExtend(request, params)));
               })
        .share();
  }

  /**
   * @method
   * @name bitmex#fetchClosedOrders
   * @description fetches information on multiple closed orders made by the user
   * @see https://www.bitmex.com/api/explorer/#!/Order/Order_getOrders
   * @param {string} symbol unified market symbol of the market orders were made
   * in
   * @param {int} [since] the earliest time in ms to fetch orders for
   * @param {int} [limit] the maximum number of order structures to retrieve
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {Order[]} a list of [order structures]{@link
   * https://docs.ccxt.com/?id=order-structure}
   */
  std::shared_future<ccxt::any> fetchClosedOrders(
      ccxt::any symbol = ccxt::any{}, ccxt::any since = ccxt::any{},
      ccxt::any limit = ccxt::any{}, ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 // Bitmex barfs if you set 'open': false in the filter...
                 ccxt::any orders = awaitValue(
                     this->fetchOrders(symbol, since, limit, params));
                 return this->filterByArray(
                     orders, std::string("status"),
                     ccxt::list{std::string("closed"), std::string("canceled")},
                     false);
               })
        .share();
  }

